const settings=new Map(),defaults={query:'',role:'',status:'',page:0,source:''},pageSize=30;
const controlled=['events','campaigns','library','rehab'];
const protectedModules=['health','coaches','clubs','finance','chat'];
const sourceLabels={accounts:'users',identity:'identity',trainingPro:'trainingPro'};
export function updateMasterAdminFilter(id,data){const old=settings.get(id)||defaults;settings.set(id,{...old,query:String(data.query||'').trim().slice(0,100),role:['athlete','coach','gym','admin'].includes(data.role)?data.role:'',status:['active','suspended','verified','protected'].includes(data.status)?data.status:'',source:[...controlled,'accounts','identity','trainingPro','nutrition'].includes(data.source)?data.source:'',page:0})}
export function moveMasterAdminPage(id,direction){const old=settings.get(id)||defaults;settings.set(id,{...old,page:Math.max(0,old.page+(direction==='next'?1:-1))})}
export function resetMasterAdmin(){settings.clear()}
const stat=(t,k,v)=>`<div class="stat-box"><b class="stat green">${v}</b><small>${t(k)}</small></div>`;
const nav=(t,btn,id,label=id)=>btn(t(label),'nav',`data-id="${id}"`,'secondary');
const option=(h,v,label,value)=>`<option value="${h(v)}" ${v===value?'selected':''}>${h(label)}</option>`;
const choose=(t,h,name,label,values,value)=>`<label>${t(label)}<select name="${name}">${option(h,'',t('all'),value)}${values.map(([v,k])=>option(h,v,t(k),value)).join('')}</select></label>`;
const statusLabel=p=>p.suspended?'masterSuspended':'masterAccountActive';

export function masterAdminPage({state,t,h,btn}){
  const a=state.masterAdmin;if(!a||a.contextKey!==state.identity?.active?.key||!state.identity.permissions.includes('platform.admin'))return '';
  const f=settings.get(state.me.id)||defaults,q=f.query.toLowerCase();
  const accounts=a.accounts.filter(p=>(!q||p.name.toLowerCase().includes(q))&&(!f.role||p.role===f.role)&&(!f.status||(f.status==='active'?!p.suspended:f.status==='suspended'?p.suspended:f.status==='verified'?p.verified:p.protected))).sort((x,y)=>x.name.localeCompare(y.name));
  const maxPage=Math.max(0,Math.ceil(accounts.length/pageSize)-1),page=Math.min(maxPage,f.page),shown=accounts.slice(page*pageSize,(page+1)*pageSize);
  const row=p=>`<div class="row rule wrap"><div class="grow"><b>${h(p.name)}</b><div class="row wrap"><small>${t(p.role)}</small>${p.verified?`<span class="badge green">${t('verified')}</span>`:''}<span class="badge ${p.suspended?'gold':'green'}">${t(statusLabel(p))}</span>${p.protected?`<span class="badge">${t('masterProtected')}</span>`:''}</div></div>${!p.protected?btn(t(p.suspended?'restore':'suspend'),'masterAdminAction',`data-op="accountStatus" data-id="${h(p.id)}" data-enabled="${!p.suspended}"`,p.suspended?'secondary':'danger'):''}</div>`;
  const flags=controlled.map(m=>{const c=a.counts[m];return `<details class="workspace-card" data-disclosure-key="master:${m}"><summary><span class="row space wrap"><b>${t(m)}</b><span class="badge ${a.flags[m]?'green':'gold'}">${t(a.flags[m]?'programEnable':'programDisable')}</span></span></summary><div class="workspace-card-body stack"><small>${t('masterContentTotal')}: ${c.total} · ${t('programStatus_published')}: ${c.published} · ${t('programStatus_draft')}: ${c.draft} · ${t('programStatus_archived')}: ${c.archived}</small><div class="row wrap">${btn(t(a.flags[m]?'programDisable':'programEnable'),'programAction',`data-module="${m}" data-op="flag" data-enabled="${!a.flags[m]}"`,'secondary')}${nav(t,btn,m,'openModule')}</div></div></details>`}).join('');
  const audit=a.audit.filter(x=>!f.source||x.source===f.source);
  return `<div class="stack"><section class="hero workspace-hero"><span class="eyebrow">MUSCLIVO LIVE / MASTER ADMIN</span><h1>${t('masterAdmin')}</h1><p>${t('masterIntro')}</p><span class="badge gold">${t('masterLocalOnly')}</span></section><section class="card stack"><h2>${t('masterOverview')}</h2><div class="grid">${stat(t,'users',a.summary.accounts)}${stat(t,'active30',a.summary.active30)}${stat(t,'masterSuspended',a.summary.suspended)}${stat(t,'clubs',a.summary.clubs)}${stat(t,'reports',a.summary.pendingReports)}${stat(t,'verifyRequests',a.summary.pendingVerification)}${stat(t,'exerciseLibrary',a.summary.exercises)}${stat(t,'masterFoodCatalog',a.summary.foods)}</div><div class="row wrap">${Object.entries(a.roles).map(([r,count])=>`<span class="badge">${t(r)}: ${count}</span>`).join('')}</div><p class="muted">${t('programAdminNotice')}</p></section><section class="card stack"><h2>${t('masterControls')}</h2><p>${t('masterRolloutHint')}</p><div class="grid workspace-grid">${flags}</div><div class="row wrap">${nav(t,btn,'trainingPro')}${nav(t,btn,'nutrition')}</div><h3>${t('masterProtectedModules')}</h3><p class="muted">${t('masterProtectedHint')}</p><div class="row wrap">${protectedModules.map(m=>`<span class="badge">${t(m)}</span>`).join('')}</div></section><section class="card stack"><h2>${t('masterAccounts')}</h2><form class="stack" data-form="masterAdminFilter"><label>${t('masterAccountSearch')}<input type="search" name="query" maxlength="100" value="${h(f.query)}"></label><div class="grid">${choose(t,h,'role','role',['athlete','coach','gym','admin'].map(r=>[r,r]),f.role)}${choose(t,h,'status','masterAccountStatus',[['active','masterAccountActive'],['suspended','masterSuspended'],['verified','verified'],['protected','masterProtected']],f.status)}</div>${hiddenSource(h,f.source)}<button type="submit" class="secondary">${t('search')}</button></form><p class="muted">${t('masterResults')}: ${accounts.length}</p>${shown.map(row).join('')||`<p class="empty">${t('noItems')}</p>`}${accounts.length>pageSize?`<div class="row wrap space">${page>0?btn(t('masterPrevious'),'masterAdminPage','data-id="previous"','chip'):''}<small>${page+1} / ${maxPage+1}</small>${page<maxPage?btn(t('masterNext'),'masterAdminPage','data-id="next"','chip'):''}</div>`:''}</section><section class="card stack"><h2>${t('verifyRequests')} · ${a.verifications.length}</h2>${a.verifications.map(v=>`<details data-disclosure-key="master-verify:${h(v.id)}"><summary>${h(v.name)} · ${t(v.role)}</summary><p class="post-text">${h(v.text)}</p><div class="row wrap">${btn(t('accept'),'masterAdminAction',`data-op="verify" data-id="${h(v.id)}" data-accept="true"`,'primary')}${btn(t('decline'),'masterAdminAction',`data-op="verify" data-id="${h(v.id)}" data-accept="false"`,'secondary')}</div></details>`).join('')||`<p class="empty">${t('noItems')}</p>`}</section><section class="card stack"><h2>${t('masterRolesAndReports')}</h2><p>${t('masterModeratorCount')}: ${a.platformModeratorCount} · ${t('reports')}: ${a.summary.pendingReports}</p><p>${t(a.canAssign?'masterCanAssign':'masterRestrictedAssign')}</p>${nav(t,btn,'identity','identity')}</section><section class="card stack"><h2>${t('audit')}</h2><p class="muted">${t('masterAuditHint')}</p><form class="row wrap" data-form="masterAdminFilter">${['query','role','status'].map(k=>`<input type="hidden" name="${k}" value="${h(f[k])}">`).join('')}${choose(t,h,'source','masterAuditSource',['accounts','identity','trainingPro','nutrition',...controlled].map(s=>[s,sourceLabels[s]||s]),f.source)}<button type="submit" class="secondary">${t('search')}</button></form>${audit.map(x=>`<div class="rule stack"><div class="row space wrap"><b>${h(x.operation)}</b><span class="badge">${t(sourceLabels[x.source]||x.source)}</span></div><small>${h(x.actor||'—')} · ${h(new Date(x.at).toLocaleString())}</small></div>`).join('')||`<p class="empty">${t('noItems')}</p>`}</section></div>`;
}
const hiddenSource=(h,value)=>`<input type="hidden" name="source" value="${h(value)}">`;
